package com.company.skillplatform.audit.application;import com.company.skillplatform.audit.infrastructure.entity.DownloadLogEntity;import com.company.skillplatform.audit.infrastructure.repository.DownloadLogRepository;import com.company.skillplatform.user.infrastructure.repository.IamUserRepository;import org.springframework.stereotype.Service;@Service public class DownloadAuditService{private final DownloadLogRepository logs;private final IamUserRepository users;public DownloadAuditService(DownloadLogRepository l,IamUserRepository u){logs=l;users=u;}public void record(Long userId,Long artifactId,Long bundleId,String objectKey){users.findById(userId).ifPresent(u->logs.save(new DownloadLogEntity(u,artifactId,bundleId,objectKey)));}}
